// Find (c1,c2,t) where all-f32 vs f64-then-narrow give DIFFERENT f32 bits.
fn lerp_f32(c1: f32, c2: f32, t: f32) -> f32 { c1 * (1.0f32 - t) + c2 * t }
fn lerp_f64(c1: f32, c2: f32, t: f32) -> f32 {
    ((c1 as f64) * (1.0f64 - t as f64) + (c2 as f64) * (t as f64)) as f32
}
struct R(u64);
impl R { fn n(&mut self) -> u32 { self.0 ^= self.0 << 13; self.0 ^= self.0 >> 7; self.0 ^= self.0 << 17; (self.0 >> 32) as u32 } }
fn main() {
    let mut r = R(0x2026_0810_1234_5678);
    let mut found = 0usize;
    let mut tries = 0u64;
    // print args lines where the two candidates differ in BITS
    while found < 40 && tries < 40_000_000 {
        tries += 1;
        // 4-decimal-ish random values in [0,1)
        let mk = |x: u32| -> f32 { (x % 1_000_000) as f32 / 1_000_000.0 };
        let c1 = mk(r.n()); let c2 = mk(r.n()); let t = mk(r.n());
        let a = lerp_f32(c1, c2, t); let b = lerp_f64(c1, c2, t);
        if a.to_bits() != b.to_bits() {
            found += 1;
            println!("{:.6} {:.6} {:.6} | f32={:.9e}({:#x}) f64n={:.9e}({:#x})",
                c1, c2, t, a, a.to_bits(), b, b.to_bits());
        }
    }
    eprintln!("tries={} found={}", tries, found);
}
