fn fma_v(c1: f32, c2: f32, t: f32) -> f32 { c1.mul_add(1.0f32 - t, c2 * t) }
// 6-significant-digit correctly-rounded decimal of the f32's exact value
fn sig6(x: f32) -> String { format!("{:.5e}", x as f64) }
struct R(u64);
impl R { fn n(&mut self) -> u64 { self.0 ^= self.0<<13; self.0 ^= self.0>>7; self.0 ^= self.0<<17; self.0 } }
