// Exact printf("%g", (double)f) with precision 6, for f32. Decimal-digit bignum, no float printing.
const P: usize = 6;

fn mul_small(d: &mut Vec<u8>, k: u8) { // d is little-endian decimal digits
    let mut carry = 0u32;
    for x in d.iter_mut() { let v = *x as u32 * k as u32 + carry; *x = (v % 10) as u8; carry = v / 10; }
    while carry > 0 { d.push((carry % 10) as u8); carry /= 10; }
}

/// exact decimal: value == D * 10^-k, returns (digits big-endian, k)
fn exact_decimal(v: f32) -> (Vec<u8>, i32) {
    let bits = v.to_bits();
    let raw_exp = ((bits >> 23) & 0xff) as i32;
    let raw_man = bits & 0x7f_ffff;
    let (m, e) = if raw_exp == 0 { (raw_man, -149i32) } else { (raw_man | 0x80_0000, raw_exp - 127 - 23) };
    let mut d: Vec<u8> = Vec::new();
    let mut t = m; if t == 0 { d.push(0); } else { while t > 0 { d.push((t % 10) as u8); t /= 10; } }
    let k = if e < 0 { -e } else { 0 };
    if e >= 0 { for _ in 0..e { mul_small(&mut d, 2); } } else { for _ in 0..(-e) { mul_small(&mut d, 5); } }
    while d.len() > 1 && *d.last().unwrap() == 0 { d.pop(); }
    d.reverse();
    (d, k)
}

pub fn fmt_g(v: f32) -> String {
    let neg = v.is_sign_negative();
    let sign = if neg { "-" } else { "" };
    if v.is_nan() { return format!("{}nan", sign); }
    if v.is_infinite() { return format!("{}inf", sign); }
    if v == 0.0 { return format!("{}0", sign); }
    let (digits, k) = exact_decimal(v);
    let nd = digits.len() as i32;
    // value = 0.d1d2.. * 10^nd * 10^-k  => d1.d2.. * 10^X
    let mut x = nd - 1 - k;
    // round to P significant digits, ties-to-even, using the EXACT tail
    let mut out: Vec<u8> = if (nd as usize) <= P { digits.clone() } else {
        let mut head = digits[..P].to_vec();
        let tail = &digits[P..];
        let first = tail[0];
        let rest_nonzero = tail[1..].iter().any(|&c| c != 0);
        let up = first > 5 || (first == 5 && (rest_nonzero || head[P-1] % 2 == 1));
        if up {
            let mut i = P as i32 - 1;
            loop {
                if i < 0 { head.insert(0, 1); x += 1; head.truncate(P); break; }
                if head[i as usize] == 9 { head[i as usize] = 0; i -= 1; } else { head[i as usize] += 1; break; }
            }
        }
        head
    };
    while out.len() < 1 { out.push(0); }
    let ds: String = out.iter().map(|d| (b'0' + d) as char).collect();
    // %g style choice, AFTER rounding
    if x < -4 || x >= P as i32 {
        let mut frac: String = ds.chars().skip(1).take(P - 1).collect();
        while frac.ends_with('0') { frac.pop(); }
        let mant = if frac.is_empty() { ds[..1].to_string() } else { format!("{}.{}", &ds[..1], frac) };
        format!("{}{}e{}{:02}", sign, mant, if x < 0 { '-' } else { '+' }, x.abs())
    } else if x >= 0 {
        let ip: String = ds.chars().take((x + 1) as usize).collect();
        let ip = if ip.len() < (x + 1) as usize { format!("{}{}", ip, "0".repeat((x + 1) as usize - ip.len())) } else { ip };
        let mut frac: String = ds.chars().skip((x + 1) as usize).collect();
        while frac.ends_with('0') { frac.pop(); }
        if frac.is_empty() { format!("{}{}", sign, ip) } else { format!("{}{}.{}", sign, ip, frac) }
    } else {
        let mut frac = format!("{}{}", "0".repeat((-x - 1) as usize), ds);
        while frac.ends_with('0') { frac.pop(); }
        if frac.is_empty() { format!("{}0", sign) } else { format!("{}0.{}", sign, frac) }
    }
}

fn main() {
    let mut args = std::env::args().skip(1);
    if let Some(a) = args.next() {
        // mode: format each remaining arg parsed as f32 (for spot checks)
        if a == "-f" { for s in args { let v: f32 = s.parse().unwrap(); println!("{}", fmt_g(v)); } return; }
    }
    // default: emit "args<TAB>expected" lines for oracle diffing (ratio=0 => out == (r1,g1,b1))
    let mut seeds: Vec<String> = Vec::new();
    for n in [0u32,1,5,10,100000,999999,1000000,1234565,1048565,8388605,16777215,1234575,2097125] { seeds.push(n.to_string()); }
    for s in ["0.5","0.1","0.0001","0.00001","1e-5","9.999995e-05","0.000099999949","999999.5","9999995","1e20","3.4e38","1.5e20","1.2e7","0.3","0.7","0.2","12345.65","1.0000005","0.9999995","inf","-inf","nan","-nan","0","-0.0"] { seeds.push(s.to_string()); }
    for s in &seeds {
        if let Ok(v) = s.parse::<f32>() { println!("{}\t{}", s, fmt_g(v)); }
    }
}
RS
