// x86 SSE binary op: dst is the FIRST operand; NaN preference dst then src
fn ss_mul(a: f32, b: f32) -> f32 {
    if a.is_nan() { q(a) } else if b.is_nan() { q(b) }
    else if (a.is_infinite() && b == 0.0) || (b.is_infinite() && a == 0.0) { f32::from_bits(QN) }
    else { a * b }
