fn ss_add(a: f32, b: f32) -> f32 {
    if a.is_nan() { q(a) } else if b.is_nan() { q(b) }
    else if a.is_infinite() && b.is_infinite() && a != b { f32::from_bits(QN) }
    else { a + b }
}
// 8 candidate orderings: (swap mul-lhs, swap mul-rhs, swap add)
fn cand(i: usize, c1: f32, c2: f32, t: f32) -> f32 {
    let om = 1.0f32 - t;
    let l = if i & 1 == 0 { ss_mul(c1, om) } else { ss_mul(om, c1) };
    let r = if i & 2 == 0 { ss_mul(c2, t) } else { ss_mul(t, c2) };
    if i & 4 == 0 { ss_add(l, r) } else { ss_add(r, l) }
}
