#[derive(Debug, PartialEq)] pub enum StofErr { Invalid, OutOfRange }
fn is_ws(c: u8) -> bool { matches!(c, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') }
fn lower(c: u8) -> u8 { c | 0x20 }
fn hexval(c: u8) -> Option<u32> { match c { b'0'..=b'9' => Some((c-b'0') as u32),
    b'a'..=b'f' => Some((c-b'a'+10) as u32), b'A'..=b'F' => Some((c-b'A'+10) as u32), _ => None } }

/// Exact hex -> f32, round-to-nearest-even. Returns (value, inexact, tie).
fn hex_to_f32(digits: &[u8], point_at: usize, pexp: i64, neg: bool) -> (f32, bool, bool) {
    // significand = digits interpreted as hex integer; value = sig * 16^(point_at - ndig) * 2^pexp
    let mut sig: u128 = 0; let mut extra_shift: i64 = 0; let mut sticky = false;
    for (i, &d) in digits.iter().enumerate() {
        let v = hexval(d).unwrap() as u128;
        if sig < (1u128 << 100) { sig = (sig << 4) | v; }
        else { extra_shift += 4; if v != 0 { sticky = true; } }
        let _ = i;
    }
    let frac_digits = digits.len() as i64 - point_at as i64;
    let mut e2 = pexp - 4 * frac_digits + extra_shift;
    if sig == 0 { return (if neg { -0.0 } else { 0.0 }, false, false); }
    // normalize so sig has exactly 25 bits (24 mantissa + 1 round), tracking sticky
    let bl = 128 - sig.leading_zeros() as i64;
    let target = 25i64;
    if bl > target { let sh = bl - target;
        if (sig & ((1u128 << sh) - 1)) != 0 { sticky = true; }
        sig >>= sh; e2 += sh;
    } else { let sh = target - bl; sig <<= sh; e2 -= sh; }
    // value = sig * 2^e2, sig in [2^24, 2^25)
    // f32: mantissa m (24 bits incl implicit) with exponent >= -149
    let mut round_bit = (sig & 1) != 0; let mut m = (sig >> 1) as u64; let mut e = e2 + 1;
    // subnormal handling: need e >= -149 with m 24 bits => value = m * 2^e
    if e < -149 { let sh = -149 - e;
        if sh >= 64 { let allz = m == 0; sticky |= !allz || round_bit; round_bit = false; m = 0; e = -149; }
        else {
            if round_bit { sticky = true; }
            if sh >= 1 { let lost = m & ((1u64 << sh) - 1); if (lost & ((1u64<<(sh-1))-1)) != 0 { sticky = true; }
                         round_bit = (lost >> (sh-1)) & 1 != 0; m >>= sh; e = -149; }
        }
    }
    let tie = round_bit && !sticky;
    let inexact = round_bit || sticky;
    if round_bit && (sticky || (m & 1) != 0) { m += 1; if m >= (1u64 << 24) && e > -149 { m >>= 1; e += 1; }
                                              else if m >= (1u64 << 24) { m >>= 1; e += 1; } }
    // assemble
    let val: f32 = if m == 0 { 0.0 } else {
        let mut mm = m; let mut ee = e;
        while mm < (1u64 << 23) && ee > -149 { mm <<= 1; ee -= 1; }        // normalize up
        if mm >= (1u64 << 24) { mm >>= 1; ee += 1; }
        if ee + 23 > 127 { f32::INFINITY }
        else if mm < (1u64 << 23) { f32::from_bits(mm as u32) }            // subnormal (ee == -149)
        else { let biased = (ee + 23 + 127) as u32; f32::from_bits((biased << 23) | ((mm as u32) & 0x7f_ffff)) }
    };
    (if neg { -val } else { val }, inexact, tie)
}

pub fn stof(s: &[u8]) -> Result<f32, StofErr> {
    let n = s.len(); let mut i = 0usize;
    while i < n && is_ws(s[i]) { i += 1; }
    let mut neg = false;
    if i < n && (s[i] == b'+' || s[i] == b'-') { neg = s[i] == b'-'; i += 1; }
    // inf / infinity
    if i + 3 <= n && lower(s[i])==b'i' && lower(s[i+1])==b'n' && lower(s[i+2])==b'f' {
        return Ok(if neg { f32::NEG_INFINITY } else { f32::INFINITY });
    }
    // nan
    if i + 3 <= n && lower(s[i])==b'n' && lower(s[i+1])==b'a' && lower(s[i+2])==b'n' {
        return Ok(f32::from_bits(if neg { 0xffc00000 } else { 0x7fc00000 }));
    }
    // hex
    if i + 1 < n && s[i]==b'0' && lower(s[i+1])==b'x' {
        let mut j = i + 2; let mut digs: Vec<u8> = Vec::new(); let mut point: Option<usize> = None;
        while j < n { if hexval(s[j]).is_some() { digs.push(s[j]); j += 1; }
                      else if s[j]==b'.' && point.is_none() { point = Some(digs.len()); j += 1; }
                      else { break; } }
        if digs.is_empty() { return Ok(if neg { -0.0 } else { 0.0 }); }   // "0x" -> parses just the "0"
        let point_at = point.unwrap_or(digs.len());
        let mut pexp: i64 = 0;
        if j < n && lower(s[j])==b'p' {
            let mut k = j + 1; let mut eneg = false;
            if k < n && (s[k]==b'+'||s[k]==b'-') { eneg = s[k]==b'-'; k += 1; }
            let st = k; let mut v: i64 = 0;
            while k < n && s[k].is_ascii_digit() { v = (v*10 + (s[k]-b'0') as i64).min(1_000_000); k += 1; }
            if k > st { pexp = if eneg { -v } else { v }; }
        }
        let (val, inexact, tie) = hex_to_f32(&digs, point_at, pexp, neg);
        if val.is_infinite() { return Err(StofErr::OutOfRange); }
        if val == 0.0 { return if inexact { Err(StofErr::OutOfRange) } else { Ok(val) }; }
        if val.abs() < f32::MIN_POSITIVE && tie { return Err(StofErr::OutOfRange); }  // hex: ties only
        return Ok(val);
    }
    // decimal
    let start = i; let mut ndig = 0usize; let mut mant: Vec<u8> = Vec::new(); let mut dp: Option<usize> = None;
    while i < n { if s[i].is_ascii_digit() { mant.push(s[i]); ndig += 1; i += 1; }
                  else if s[i]==b'.' && dp.is_none() { dp = Some(mant.len()); i += 1; }
                  else { break; } }
    if ndig == 0 { return Err(StofErr::Invalid); }
    let frac = mant.len() - dp.unwrap_or(mant.len());
    let mut exp: i64 = 0;
    if i < n && lower(s[i])==b'e' {
        let mut k = i + 1; let mut eneg = false;
        if k < n && (s[k]==b'+'||s[k]==b'-') { eneg = s[k]==b'-'; k += 1; }
        let st = k; let mut v: i64 = 0;
        while k < n && s[k].is_ascii_digit() { v = (v*10 + (s[k]-b'0') as i64).min(1_000_000); k += 1; }
        if k > st { exp = if eneg { -v } else { v }; }
    }
    let _ = start;
    let ms = String::from_utf8_lossy(&mant).to_string();
    let e10 = exp - frac as i64;
    let norm = format!("{}{}e{}", if neg { "-" } else { "" }, if ms.is_empty() { "0" } else { &ms }, e10);
    let v32: f32 = norm.parse().unwrap_or(if neg { -0.0 } else { 0.0 });
    let v64: f64 = norm.parse().unwrap_or(0.0);
    let all_zero = mant.iter().all(|&c| c == b'0');
    if v32.is_infinite() { return Err(StofErr::OutOfRange); }
    if v32 == 0.0 { return if all_zero { Ok(v32) } else { Err(StofErr::OutOfRange) }; }
    if v32.abs() < f32::MIN_POSITIVE && (v32 as f64) != v64 { return Err(StofErr::OutOfRange); }
    Ok(v32)
}
