/// glibc hex-path ERANGE predicate, fitted on 112 oracle probes.
/// sig: exact hex significand as an integer; e: exact binary exponent so value = sig * 2^e.
/// ERANGE iff the significand TRUNCATED TO 24 BITS loses a set bit to the 2^-149 exponent floor,
/// except that a value which rounds UP into the normal range is only flagged on an exact tie.
pub fn hex_underflow(sig: u128, e: i64, rounded_is_normal: bool, exact_tie: bool) -> bool {
    if sig == 0 { return false; }
    let bl = 128 - sig.leading_zeros() as i64;
    let (s24, e24) = if bl > 24 { (sig >> (bl - 24), e + (bl - 24)) } else { (sig, e) };
    let lowest = e24 + s24.trailing_zeros() as i64;
    if lowest >= -149 { return false; }
    if rounded_is_normal && !exact_tie { return false; }
    true
}
