//! Exact reimplementation of C's `printf("%g", value)` with the default precision of 6,
//! which is what `std::cout << some_float` produces in the original C++ program.
//!
//! # Why this cannot use Rust's own float formatting
//!
//! `format!("{}", x)` produces the *shortest* decimal string that round-trips back to `x`.
//! `printf` does something quite different: it rounds the float's **exact** binary value to
//! `N` significant decimal digits, breaking exact ties to even. The two disagree, e.g. the
//! `f32` nearest to `1234565.0` formats as `1234565` under Rust's shortest-repr rules but as
//! `1.23456e+06` under `%g` (an exact tie, rounded down to the even digit `6`).
//!
//! So we expand the float to its exact decimal digits using integer arithmetic and round
//! those ourselves. Every finite binary float *is* a finite decimal, so this is always exact:
//! for `v = m * 2^e` with `e < 0` we have `v = (m * 5^-e) * 10^e`, and for `e >= 0` simply
//! `v = (m * 2^e) * 10^0`.

/// `%g`'s default precision: the number of significant digits kept.
const PRECISION: usize = 6;

/// A non-negative integer held as decimal digits, least-significant first.
///
/// Multiplying by a small constant is all we need, and doing the arithmetic in base 10 means
/// the digits we want fall out directly with no binary-to-decimal conversion step.
struct DecDigits(Vec<u8>);

impl DecDigits {
    /// Digits of `n`, least-significant first.
    fn from_u32(n: u32) -> Self {
        let mut d = Vec::with_capacity(40);
        let mut n = n;
        if n == 0 {
            d.push(0);
        } else {
            while n > 0 {
                d.push((n % 10) as u8);
                n /= 10;
            }
        }
        DecDigits(d)
    }

    /// `self *= k`, for a single-digit `k`.
    fn mul_small(&mut self, k: u8) {
        let mut carry = 0u32;
        for digit in self.0.iter_mut() {
            let v = *digit as u32 * k as u32 + carry;
            *digit = (v % 10) as u8;
            carry = v / 10;
        }
        while carry > 0 {
            self.0.push((carry % 10) as u8);
            carry /= 10;
        }
    }

    /// Consume into most-significant-first digits with leading zeros removed.
    fn into_big_endian(mut self) -> Vec<u8> {
        while self.0.len() > 1 && *self.0.last().unwrap() == 0 {
            self.0.pop();
        }
        self.0.reverse();
        self.0
    }
}

/// Split a finite non-zero `f32` into `(significand, exponent)` with `value = significand * 2^exponent`.
fn decompose(v: f32) -> (u32, i32) {
    let bits = v.to_bits();
    let biased_exp = ((bits >> 23) & 0xff) as i32;
    let fraction = bits & 0x007f_ffff;
    if biased_exp == 0 {
        // Subnormal: no implicit leading 1, fixed exponent.
        (fraction, -149)
    } else {
        // Normal: restore the implicit leading 1; bias 127, and 23 fractional mantissa bits.
        (fraction | 0x0080_0000, biased_exp - 127 - 23)
    }
}

/// Exact decimal expansion of a finite non-zero `f32`.
///
/// Returns `(digits, scale)` with the digits most-significant-first and no leading zeros, such
/// that `|v| == digits_as_integer * 10^-scale` exactly.
fn exact_decimal(v: f32) -> (Vec<u8>, i32) {
    let (significand, exponent) = decompose(v);
    let mut digits = DecDigits::from_u32(significand);
    let scale = if exponent < 0 { -exponent } else { 0 };
    if exponent >= 0 {
        // v = significand * 2^exponent, an integer.
        for _ in 0..exponent {
            digits.mul_small(2);
        }
    } else {
        // v = significand * 5^-exponent * 10^exponent.
        for _ in 0..-exponent {
            digits.mul_small(5);
        }
    }
    (digits.into_big_endian(), scale)
}

/// Round a big-endian digit string to `PRECISION` significant digits, half-to-even.
///
/// `decimal_exp` is the exponent of the leading digit and is bumped when rounding up carries
/// past the front (e.g. `999999.5` -> `1000000`, moving `%g` from `%f` style into `%e` style).
fn round_to_precision(digits: &[u8], decimal_exp: &mut i32) -> Vec<u8> {
    if digits.len() <= PRECISION {
        return digits.to_vec();
    }
    let mut kept = digits[..PRECISION].to_vec();
    let dropped = &digits[PRECISION..];

    // Compare the dropped tail against exactly one half.
    let first_dropped = dropped[0];
    let tail_has_more = dropped[1..].iter().any(|&d| d != 0);
    let round_up = match first_dropped.cmp(&5) {
        core::cmp::Ordering::Greater => true,
        core::cmp::Ordering::Less => false,
        // Exact tie: round half to even, matching glibc under the default rounding mode.
        core::cmp::Ordering::Equal => tail_has_more || kept[PRECISION - 1] % 2 == 1,
    };

    if round_up {
        let mut i = PRECISION;
        loop {
            if i == 0 {
                // Carried out of the most significant digit: 999999 -> 1000000.
                kept.insert(0, 1);
                kept.truncate(PRECISION);
                *decimal_exp += 1;
                break;
            }
            i -= 1;
            if kept[i] == 9 {
                kept[i] = 0;
            } else {
                kept[i] += 1;
                break;
            }
        }
    }
    kept
}

/// Render `digits` (already rounded) in `%e` style: `d.dddddE±XX`, trailing zeros stripped.
fn style_e(sign: &str, digits: &str, decimal_exp: i32) -> String {
    let mut fraction: String = digits.chars().skip(1).take(PRECISION - 1).collect();
    while fraction.ends_with('0') {
        fraction.pop();
    }
    let mantissa = if fraction.is_empty() {
        digits[..1].to_string()
    } else {
        format!("{}.{}", &digits[..1], fraction)
    };
    // printf always emits a sign and at least two exponent digits.
    format!(
        "{}{}e{}{:02}",
        sign,
        mantissa,
        if decimal_exp < 0 { '-' } else { '+' },
        decimal_exp.abs()
    )
}

/// Render `digits` (already rounded) in `%f` style, trailing zeros and a bare point stripped.
fn style_f(sign: &str, digits: &str, decimal_exp: i32) -> String {
    if decimal_exp >= 0 {
        let int_len = decimal_exp as usize + 1;
        let mut integer: String = digits.chars().take(int_len).collect();
        // The value can have more integer places than we have significant digits (e.g. 100000
        // from 6 digits is fine, but 1e+05 rounded to "1" needs zero padding).
        while integer.len() < int_len {
            integer.push('0');
        }
        let mut fraction: String = digits.chars().skip(int_len).collect();
        while fraction.ends_with('0') {
            fraction.pop();
        }
        if fraction.is_empty() {
            format!("{}{}", sign, integer)
        } else {
            format!("{}{}.{}", sign, integer, fraction)
        }
    } else {
        // -4 <= decimal_exp <= -1: a leading "0." then |decimal_exp|-1 zeros.
        let mut fraction = "0".repeat((-decimal_exp - 1) as usize);
        fraction.push_str(digits);
        while fraction.ends_with('0') {
            fraction.pop();
        }
        if fraction.is_empty() {
            format!("{}0", sign)
        } else {
            format!("{}0.{}", sign, fraction)
        }
    }
}

/// Format `v` exactly as C's `printf("%g", (double) v)` would with the default precision of 6.
///
/// This matches `std::cout << v` for `float` in the original program: the value is widened to
/// `double` (exactly) and printed with `std::cout`'s default precision of 6.
pub fn format_g(v: f32) -> String {
    let sign = if v.is_sign_negative() { "-" } else { "" };
    if v.is_nan() {
        // printf reports the sign bit of a NaN, so -NaN prints as "-nan".
        return format!("{}nan", sign);
    }
    if v.is_infinite() {
        return format!("{}inf", sign);
    }
    if v == 0.0 {
        // %g of zero is "0.00000" with trailing zeros stripped, keeping "-" for -0.0.
        return format!("{}0", sign);
    }

    let (digits, scale) = exact_decimal(v);
    // |v| == digits * 10^-scale, so the leading digit sits at 10^(len-1-scale).
    let mut decimal_exp = digits.len() as i32 - 1 - scale;
    let rounded = round_to_precision(&digits, &mut decimal_exp);
    let text: String = rounded.iter().map(|&d| (b'0' + d) as char).collect();

    // %g picks %e when the exponent is out of range, judged *after* rounding.
    if decimal_exp < -4 || decimal_exp >= PRECISION as i32 {
        style_e(sign, &text, decimal_exp)
    } else {
        style_f(sign, &text, decimal_exp)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn g(s: &str) -> String {
        format_g(s.parse::<f32>().unwrap())
    }

    #[test]
    fn plain_values() {
        assert_eq!(g("0.5"), "0.5");
        assert_eq!(g("0.1"), "0.1");
        assert_eq!(g("10"), "10");
        assert_eq!(g("100000"), "100000");
        assert_eq!(g("999999"), "999999");
        assert_eq!(g("12345.65"), "12345.7");
        assert_eq!(g("0.0001"), "0.0001");
    }

    #[test]
    fn exponent_style_switch() {
        // 1e6 is the first magnitude that needs %e at precision 6.
        assert_eq!(g("1000000"), "1e+06");
        assert_eq!(g("0.00001"), "1e-05");
        assert_eq!(g("1e20"), "1e+20");
        assert_eq!(g("3.4e38"), "3.4e+38");
        assert_eq!(g("1.2e7"), "1.2e+07");
        // Rounding carries into a new decade, which flips %f -> %e.
        assert_eq!(g("999999.5"), "1e+06");
        assert_eq!(g("9999995"), "1e+07");
        // ...and the same at the small end of the %f window.
        assert_eq!(g("9.999995e-05"), "9.99999e-05");
    }

    #[test]
    fn ties_round_half_to_even() {
        // Integers below 2^24 are exact floats, so these are genuine ties.
        assert_eq!(g("1234565"), "1.23456e+06"); // 6 is even: stay
        assert_eq!(g("1048565"), "1.04856e+06");
        assert_eq!(g("8388605"), "8.3886e+06");
        assert_eq!(g("1234575"), "1.23458e+06"); // 7 is odd: round up
        assert_eq!(g("1048585"), "1.04858e+06");
        assert_eq!(g("2097125"), "2.09712e+06");
    }

    #[test]
    fn rounding_uses_the_exact_binary_value_not_shortest_repr() {
        // 0.1234565f's exact value is slightly *above* the decimal tie, so it rounds up even
        // though the shortest representation looks like an exact tie.
        assert_eq!(g("0.1234565"), "0.123457");
        assert_eq!(g("1.0000005"), "1");
        assert_eq!(g("0.9999995"), "1");
    }

    #[test]
    fn signed_zero_and_specials() {
        assert_eq!(format_g(0.0), "0");
        assert_eq!(format_g(-0.0), "-0");
        assert_eq!(format_g(f32::INFINITY), "inf");
        assert_eq!(format_g(f32::NEG_INFINITY), "-inf");
        assert_eq!(format_g(f32::from_bits(0x7fc0_0000)), "nan");
        assert_eq!(format_g(f32::from_bits(0xffc0_0000)), "-nan");
    }

    #[test]
    fn extremes() {
        assert_eq!(format_g(f32::MIN_POSITIVE), "1.17549e-38");
        assert_eq!(format_g(f32::from_bits(1)), "1.4013e-45"); // smallest subnormal
        assert_eq!(format_g(f32::MAX), "3.40282e+38");
        assert_eq!(format_g(16_777_215.0), "1.67772e+07");
    }
}

