        assert_eq!(format_g(f32::NEG_INFINITY), "-inf");
        assert_eq!(format_g(f32::from_bits(0x7fc0_0000)), "nan");
        assert_eq!(format_g(f32::from_bits(0xffc0_0000)), "-nan");
    }

    #[test]
    fn extremes() {
        assert_eq!(format_g(f32::MIN_POSITIVE), "1.17549e-38");
        assert_eq!(format_g(f32::from_bits(1)), "1.4013e-45"); // smallest subnormal
        assert_eq!(format_g(f32::MAX), "3.40282e+38");
        assert_eq!(format_g(16_777_215.0), "1.67772e+07");
    }
}

