    Some(if negative { -value } else { value })
}

/// Assemble `significand * 2^exponent` into an `f32`, rounding to nearest with ties to even.
///
/// `sticky` carries "there were more non-zero bits below what `significand` holds", which the
/// caller sets when it had to drop low-order digits.
///
/// Returns the value plus the two facts the `ERANGE` predicates need: whether the conversion was
/// inexact, and whether it was an *exact* tie.
struct Rounded {
    value: f32,
    inexact: bool,
    exact_tie: bool,
}

fn round_to_f32(significand: u128, exponent: i64, mut sticky: bool) -> Rounded {
    if significand == 0 {
        return Rounded { value: 0.0, inexact: sticky, exact_tie: false };
    }
    let bit_len = 128 - significand.leading_zeros() as i64;

    // Two things force us to drop low bits: the 24-bit significand, and the fixed exponent floor
    // of 2^-149 below which floats become subnormal and lose precision.
    let shift = (bit_len - 24).max(-149 - exponent);

    let (mut mantissa, mut exp2, round_bit) = if shift <= 0 {
        // Everything fits; shifting left is exact.
        let left = (-shift) as u32;
        if left >= 128 {
            (0u128, exponent, false)
        } else {
            (significand << left, exponent + shift, false)
        }
    } else if shift >= 128 {
        sticky = true;
        (0u128, exponent + shift, false)
    } else {
        let sh = shift as u32;
        let lost = significand & ((1u128 << sh) - 1);
        let round_bit = (lost >> (sh - 1)) & 1 != 0;
        if sh > 1 && (lost & ((1u128 << (sh - 1)) - 1)) != 0 {
            sticky = true;
        }
        (significand >> sh, exponent + shift, round_bit)
    };

    let exact_tie = round_bit && !sticky;
    let inexact = round_bit || sticky;
    // Round half to even.
    if round_bit && (sticky || (mantissa & 1) != 0) {
        mantissa += 1;
        if mantissa >= (1u128 << 24) {
            mantissa >>= 1;
            exp2 += 1;
        }
    }

    let value = assemble(mantissa, exp2);
    Rounded { value, inexact, exact_tie }
}

/// Build a non-negative `f32` equal to `mantissa * 2^exp2`, where `mantissa < 2^24` and
/// `exp2 >= -149` unless the value is zero or overflows.
fn assemble(mantissa: u128, mut exp2: i64) -> f32 {
    if mantissa == 0 {
        return 0.0;
    }
    let mut m = mantissa;
    while m < (1u128 << 23) && exp2 > -149 {
        m <<= 1;
        exp2 -= 1;
    }
    if m >= (1u128 << 24) {
        m >>= 1;
        exp2 += 1;
    }
    if exp2 + 23 > 127 {
        return f32::INFINITY;
    }
    if m < (1u128 << 23) {
        // Subnormal: exp2 is pinned at -149 and the mantissa is the raw bit pattern.
        f32::from_bits(m as u32)
    } else {
        let biased = (exp2 + 23 + 127) as u32;
        f32::from_bits((biased << 23) | ((m as u32) & 0x007f_ffff))
    }
}

/// glibc's hexadecimal-path underflow test.
///
/// The hex path reports `ERANGE` only for precision lost to the *exponent floor*, ignoring
/// precision already lost to the 24-bit significand limit. Concretely: truncate the exact
/// significand to 24 bits and ask whether its lowest set bit falls below `2^-149`. A value that
/// rounds up into the normal range is exempt unless the rounding was an exact tie.
///
/// (This differs from the decimal path, which flags *any* inexact subnormal result. The two
/// predicates were established by differential testing against the C++ binary.)
fn hex_underflows(significand: u128, exponent: i64, rounded_is_normal: bool, exact_tie: bool) -> bool {
    if significand == 0 {
        return false;
    }
    let bit_len = 128 - significand.leading_zeros() as i64;
    let (top24, exp_of_top24) = if bit_len > 24 {
        (significand >> (bit_len - 24), exponent + (bit_len - 24))
    } else {
        (significand, exponent)
    };
    let lowest_set_bit = exp_of_top24 + top24.trailing_zeros() as i64;
    if lowest_set_bit >= -149 {
        return false;
    }
    if rounded_is_normal && !exact_tie {
        return false;
    }
    true
}

/// Strip leading and trailing zeros so that two decimals can be compared for exact equality.
///
/// Returns `(digits, exponent)` with `value == digits * 10^exponent`, no leading or trailing
/// zeros, and an empty digit list for zero.
fn canonical_decimal(digits: &[u8], mut exponent: i64) -> (Vec<u8>, i64) {
    let first = digits.iter().position(|&d| d != 0);
    let Some(first) = first else { return (Vec::new(), 0) };
    let last = digits.iter().rposition(|&d| d != 0).unwrap();
    exponent += (digits.len() - 1 - last) as i64;
    (digits[first..=last].to_vec(), exponent)
}

/// Is the decimal `digits * 10^exponent` *exactly* equal to `value`?
///
/// Both sides are put in canonical form, which makes the comparison a plain equality test with
/// no big-integer padding. Used only to decide `ERANGE` for subnormal decimal results.
fn decimal_equals_exactly(digits: &[u8], exponent: i64, value: f32) -> bool {
    let (left_digits, left_exp) = canonical_decimal(digits, exponent);
    if value == 0.0 {
        return left_digits.is_empty();
    }
    let (exact_digits, scale) = crate::cnum::fmt_g::exact_decimal(value);
    let (right_digits, right_exp) = canonical_decimal(&exact_digits, -(scale as i64));
    left_digits == right_digits && left_exp == right_exp
}

/// Parse `text` the way `std::stof` would.
///
/// Leading whitespace is skipped, trailing bytes after the number are ignored, and the result is
/// the correctly-rounded nearest `f32`.
pub fn stof(text: &[u8]) -> Result<f32, StofError> {
    let n = text.len();
    let mut i = 0usize;
    while i < n && is_space(text[i]) {
        i += 1;
    }
    let mut negative = false;
    if i < n && (text[i] == b'+' || text[i] == b'-') {
        negative = text[i] == b'-';
        i += 1;
    }

    // "inf" / "infinity", case-insensitive. Never sets ERANGE.
    if i + 3 <= n && lower(text[i]) == b'i' && lower(text[i + 1]) == b'n' && lower(text[i + 2]) == b'f' {
        return Ok(if negative { f32::NEG_INFINITY } else { f32::INFINITY });
    }
    // "nan", optionally followed by a parenthesised payload. The payload cannot change what the
    // program prints (only the sign bit is visible through %g), so it is simply skipped.
    if i + 3 <= n && lower(text[i]) == b'n' && lower(text[i + 1]) == b'a' && lower(text[i + 2]) == b'n' {
        let bits = if negative { 0xffc0_0000 } else { 0x7fc0_0000 };
        return Ok(f32::from_bits(bits));
    }

    // Hexadecimal form: 0x / 0X followed by hex digits and an optional binary exponent.
    if i + 1 < n && text[i] == b'0' && lower(text[i + 1]) == b'x' {
        return parse_hex(text, i + 2, negative);
    }

    parse_decimal(text, i, negative)
}

fn parse_hex(text: &[u8], mut i: usize, negative: bool) -> Result<f32, StofError> {
    let n = text.len();
    // Accumulate at most 32 hex digits (128 bits) exactly; fold the rest into a sticky bit and
    // an exponent adjustment. 128 bits is far more than the 25 the rounding decision needs.
    const MAX_HEX_DIGITS: usize = 32;
    let mut significand: u128 = 0;
    let mut kept = 0usize;
    let mut dropped: i64 = 0;
    let mut sticky = false;
    let mut fraction_digits: i64 = 0;
    let mut seen_point = false;
    let mut any_digit = false;

    while i < n {
        if let Some(v) = hex_digit(text[i]) {
            any_digit = true;
            if kept < MAX_HEX_DIGITS {
                significand = (significand << 4) | v as u128;
                kept += 1;
            } else {
                dropped += 1;
                if v != 0 {
                    sticky = true;
                }
            }
            if seen_point {
                fraction_digits += 1;
            }
            i += 1;
        } else if text[i] == b'.' && !seen_point {
            seen_point = true;
            i += 1;
        } else {
            break;
        }
    }

    if !any_digit {
        // `strtof` backs out of the "0x" and converts just the leading "0", so "0x" is a valid
        // parse yielding zero rather than an error.
        return Ok(if negative { -0.0 } else { 0.0 });
    }

    let mut binary_exponent: i64 = 0;
    if i < n && lower(text[i]) == b'p' {
        if let Some(e) = scan_exponent(text, i + 1) {
            binary_exponent = e;
        }
    }

    // value == significand * 2^exponent (plus the dropped low digits, tracked by `sticky`)
    let exponent = binary_exponent - 4 * fraction_digits + 4 * dropped;
    let r = round_to_f32(significand, exponent, sticky);

    if r.value.is_infinite() {
        return Err(StofError::OutOfRange);
    }
    if r.value == 0.0 {
        // Underflowed all the way to zero: an error unless the input really was zero.
        return if significand == 0 && !sticky {
            Ok(if negative { -0.0 } else { 0.0 })
        } else {
            Err(StofError::OutOfRange)
        };
    }
    let is_normal = r.value.abs() >= f32::MIN_POSITIVE;
    if hex_underflows(significand, exponent, is_normal, r.exact_tie) {
        return Err(StofError::OutOfRange);
    }
    Ok(if negative { -r.value } else { r.value })
}

fn parse_decimal(text: &[u8], mut i: usize, negative: bool) -> Result<f32, StofError> {
    let n = text.len();
    let mut digits: Vec<u8> = Vec::new();
    let mut fraction_digits: i64 = 0;
    let mut seen_point = false;
    let mut any_digit = false;

    while i < n {
        if text[i].is_ascii_digit() {
            any_digit = true;
            digits.push(text[i] - b'0');
            if seen_point {
                fraction_digits += 1;
            }
            i += 1;
        } else if text[i] == b'.' && !seen_point {
            seen_point = true;
            i += 1;
        } else {
            break;
        }
    }
    if !any_digit {
        // Nothing was consumed, so `strtof` reports no conversion.
        return Err(StofError::InvalidArgument);
    }

    let mut exponent: i64 = 0;
    if i < n && lower(text[i]) == b'e' {
        if let Some(e) = scan_exponent(text, i + 1) {
            exponent = e;
        }
    }
    let power_of_ten = exponent.saturating_sub(fraction_digits);

    // Rust's own decimal parser is correctly rounded, exactly like glibc's, so we can delegate
    // the conversion once the string has been reduced to a plain "<digits>e<exp>" form.
    let mut normalized = String::with_capacity(digits.len() + 24);
    if negative {
        normalized.push('-');
    }
    for &d in &digits {
        normalized.push((b'0' + d) as char);
    }
    normalized.push('e');
    normalized.push_str(&power_of_ten.to_string());
    let value: f32 = normalized.parse().unwrap_or(if negative { -0.0 } else { 0.0 });

    let all_zero = digits.iter().all(|&d| d == 0);
    if value.is_infinite() {
        return Err(StofError::OutOfRange);
    }
    if value == 0.0 {
        return if all_zero { Ok(value) } else { Err(StofError::OutOfRange) };
    }
    // The decimal path flags every inexact subnormal result.
    if value.abs() < f32::MIN_POSITIVE && !decimal_equals_exactly(&digits, power_of_ten, value.abs()) {
        return Err(StofError::OutOfRange);
    }
    Ok(value)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn v(s: &str) -> f32 {
        stof(s.as_bytes()).unwrap()
    }
    fn err(s: &str) -> StofError {
        stof(s.as_bytes()).unwrap_err()
    }

    #[test]
    fn plain_decimals() {
        assert_eq!(v("0.5"), 0.5);
        assert_eq!(v("  \t0.5"), 0.5);
        assert_eq!(v("\n0.5"), 0.5);
        assert_eq!(v("+.5"), 0.5);
        assert_eq!(v("-.5"), -0.5);
        assert_eq!(v(".5"), 0.5);
        assert_eq!(v("5."), 5.0);
        assert_eq!(v("+0.5"), 0.5);
    }

    #[test]
    fn trailing_garbage_is_ignored() {
        assert_eq!(v("0.5abc"), 0.5);
        assert_eq!(v("1_000"), 1.0);
        assert_eq!(v("1,5"), 1.0);
        assert_eq!(v("1.5e2x"), 150.0);
        // A dangling exponent marker is simply not consumed.
        assert_eq!(v("1e"), 1.0);
        assert_eq!(v("1e+"), 1.0);
    }

    #[test]
    fn rejected_inputs() {
        assert_eq!(err(""), StofError::InvalidArgument);
        assert_eq!(err("abc"), StofError::InvalidArgument);
        assert_eq!(err("."), StofError::InvalidArgument);
        assert_eq!(err("e5"), StofError::InvalidArgument);
        assert_eq!(err("--1"), StofError::InvalidArgument);
    }

    #[test]
    fn hex_forms() {
        assert_eq!(v("0x10"), 16.0);
        assert_eq!(v("0x1p4"), 16.0);
        assert_eq!(v("0X1P-2"), 0.25);
        assert_eq!(v("0x.8p1"), 1.0);
        assert_eq!(v("0x1p"), 1.0);
        assert_eq!(v("0x"), 0.0); // only the leading "0" is consumed
        assert_eq!(v("  +0x10p0z"), 16.0);
    }

    #[test]
    fn infinities_and_nans() {
        assert!(v("inf").is_infinite() && v("inf") > 0.0);
        assert!(v("-inf").is_infinite() && v("-inf") < 0.0);
        assert!(v("infinity").is_infinite());
        assert!(v("iNfInItY").is_infinite());
        assert!(v("nan").is_nan() && !v("nan").is_sign_negative());
        assert!(v("-nan").is_nan() && v("-nan").is_sign_negative());
        assert!(v("nan()").is_nan());
        assert!(v("nan(0x1)").is_nan());
    }

    #[test]
    fn overflow_is_out_of_range() {
        assert_eq!(err("1e400"), StofError::OutOfRange);
        assert_eq!(err("1e5000"), StofError::OutOfRange);
        assert_eq!(err("-1e5000"), StofError::OutOfRange);
        assert_eq!(err("3.5e38"), StofError::OutOfRange);
        assert_eq!(err("3.402823669209384e38"), StofError::OutOfRange);
        assert_eq!(err("0x1p128"), StofError::OutOfRange);
        // Right up to FLT_MAX is fine.
        assert_eq!(v("3.4e38"), 3.4e38);
        assert_eq!(v("3.40282346638528859812e38"), f32::MAX);
        assert_eq!(v("0x1.fffffep127"), f32::MAX);
    }

    #[test]
    fn decimal_underflow_flags_inexact_subnormals() {
        for s in ["1e-38", "1e-40", "1e-45", "1e-46", "1e-50"] {
            assert_eq!(err(s), StofError::OutOfRange, "{}", s);
        }
        // Rounds up to FLT_MIN, which is normal, so it is accepted.
        assert_eq!(v("1.1754944e-38"), f32::MIN_POSITIVE);
        // An *exact* subnormal decimal is accepted.
        let exact_smallest = "0.000000000000000000000000000000000000000000001401298464324817070923729583289916131280261941876515771757068283889791082685860601486638188362121582031250";
        assert_eq!(v(exact_smallest), f32::from_bits(1));
    }

    #[test]
    fn zero_never_underflows() {
        for s in ["0", "0.0", "0e-400", "0e400", "0.000e-999", "0x0p-99999"] {
            assert_eq!(stof(s.as_bytes()), Ok(0.0), "{}", s);
        }
        assert!(v("-0.0").is_sign_negative());
    }

    #[test]
    fn hex_underflow_predicate() {
        // Exact subnormals are fine; losing a bit to the 2^-149 floor is not.
        assert_eq!(v("0x1p-149"), f32::from_bits(1));
        assert_eq!(err("0x1p-150"), StofError::OutOfRange);
        assert_eq!(v("0x1.8p-148"), f32::from_bits(3));
        assert_eq!(err("0x1.8p-149"), StofError::OutOfRange);
        assert_eq!(err("0x1.4p-148"), StofError::OutOfRange);
        assert_eq!(err("0x1.000002p-127"), StofError::OutOfRange);
        assert_eq!(v("0x1.000002p-126"), f32::from_bits(0x0080_0001));
        // A 25-bit significand is already inexact for a normal float, so it is not "underflow".
        assert!(stof(b"0x1.000001p-149").is_ok());
        assert!(stof(b"0x1.fffffdp-127").is_ok());
        assert!(stof(b"0x1.ffffffp-127").is_ok());
        assert_eq!(err("0x1.fffffep-127"), StofError::OutOfRange);
    }

    #[test]
    fn correctly_rounded() {
        // Exact midpoint between 1.0 and the next float: ties to even keeps 1.0.
        assert_eq!(v("1.00000005960464477539062500"), 1.0);
        assert_eq!(v("0.1"), 0.1f32);
        assert_eq!(v("1.2345678901234567"), 1.2345679f32);
    }
}

