//! The `ColorSpace::ColorConverter` operations used by this program.

use super::rgb::RGB;

/// The QNaN that x86 SSE produces for an invalid operation (its "real indefinite" value).
///
/// Note that its sign bit is set, which is why an expression such as `inf * 0` prints as `-nan`
/// rather than `nan`.
const INVALID_OP_QNAN: u32 = 0xffc0_0000;

/// A single-precision multiply with x86 SSE's NaN propagation rules.
///
/// `mulss` returns its *destination* operand when that operand is a NaN, and only otherwise
/// considers the source operand. Spelling this out keeps the result independent of whatever
/// operand order the Rust compiler happens to pick, which matters because the original binary's
/// choice is baked into its machine code.
fn mul(dst: f32, src: f32) -> f32 {
    if dst.is_nan() {
        return dst;
    }
    if src.is_nan() {
        return src;
    }
    if (dst.is_infinite() && src == 0.0) || (src.is_infinite() && dst == 0.0) {
        return f32::from_bits(INVALID_OP_QNAN);
    }
    dst * src
}

/// A single-precision add with x86 SSE's NaN propagation rules. See [`mul`].
fn add(dst: f32, src: f32) -> f32 {
    if dst.is_nan() {
        return dst;
    }
    if src.is_nan() {
        return src;
    }
    if dst.is_infinite() && src.is_infinite() && dst != src {
        return f32::from_bits(INVALID_OP_QNAN);
    }
    dst + src
}

/// One component of a linear interpolation, `from * (1 - ratio) + to * ratio`.
///
/// Every operation is single-precision, matching `ColorSpace::blend`'s `float` signature; doing
/// the arithmetic in `f64` and narrowing afterwards gives a different answer often enough to be
/// visible in the printed digits, as does contracting the expression into a fused multiply-add.
///
/// `to_term_first` selects which product is the addition's destination operand. It only changes
/// the outcome when *both* products are NaN, in which case the destination wins -- and the
/// original binary's compiled code happens to use a different order for the red component than
/// for green and blue.
fn interpolate(from: f32, to: f32, ratio: f32, to_term_first: bool) -> f32 {
    let from_term = mul(from, 1.0f32 - ratio);
    let to_term = mul(to, ratio);
    if to_term_first {
        add(to_term, from_term)
    } else {
        add(from_term, to_term)
    }
}

/// Linearly interpolate between two colours, mirroring
/// `ColorSpace::ColorConverter::blend(RGB const&, RGB const&, float)`.
///
/// Each component becomes `from * (1 - ratio) + to * ratio`. The ratio is not clamped, so values
/// outside `[0, 1]` extrapolate: the original binary prints `5 5 0.5` for a ratio of `5`.
pub fn blend(from: &RGB, to: &RGB, ratio: f32) -> RGB {
    RGB::new(
