/// Each component becomes `from * (1 - ratio) + to * ratio`. The ratio is not clamped, so values
/// outside `[0, 1]` extrapolate: the original binary prints `5 5 0.5` for a ratio of `5`.
pub fn blend(from: &RGB, to: &RGB, ratio: f32) -> RGB {
