//! Entry point for the colour-blend test program: a port of `color/tests/test7.cpp`.
//!
//! The original reads five colour components and a blend ratio from the command line, blends two
//! colours, and prints the result:
//!
//! ```text
//! float r1 = 0.3f, g1 = 0.4f, b1 = 0.5f;
//! float r2 = 0.7f, g2 = 0.2f, b2 = 0.1f;
//! float ratio = 0.3f;
//! if (argc > 5) { r1 = stof(argv[1]); … g2 = stof(argv[5]); }
//! if (argc > 6) { ratio = stof(argv[6]); }
//! std::cout << result.r << " " << result.g << " " << result.b << std::endl;
//! ```
//!
//! Two details of that code are easy to miss and are reproduced deliberately rather than fixed:
//!
//! * `b2` is never read from the command line. It keeps its default of `0.1f` no matter what is
//!   passed. The sixth positional argument becomes the *ratio*, so a caller who believes they are
//!   supplying `r1 g1 b1 r2 g2 b2 ratio` is really supplying `r1 g1 b1 r2 g2 ratio` followed by an
//!   argument that is silently discarded.
//! * Nothing beyond `argv[6]` is ever looked at, so a seventh argument may be arbitrary garbage
//!   without provoking an error.

// Declared with explicit paths so that this file builds both on its own (`rustc test7.rs`) and as
// the `[[bin]]` target of the surrounding Cargo package.
#[path = "src/cnum/mod.rs"]
mod cnum;
#[path = "src/color/mod.rs"]
mod color;

use cnum::fmt_g::format_g;
use cnum::strtof::{stof, StofError};
use color::{blend, RGB};

use std::io::Write;
// The original parses raw `char*` bytes, which need not be valid UTF-8. `std::env::args` would
// panic on such an argument, so the raw bytes are taken from `args_os` instead.
use std::os::unix::ffi::OsStrExt;

/// Report an uncaught C++ exception the way libstdc++'s terminate handler does, then die from
/// `SIGABRT` so the exit status matches the original (128 + 6 = 134).
fn terminate(error: StofError) -> ! {
    let mut stderr = std::io::stderr();
    let _ = write!(
        stderr,
        "terminate called after throwing an instance of '{}'\n  what():  stof\n",
        error.cxx_type_name()
    );
    let _ = stderr.flush();
    std::process::abort();
}

/// Parse one argument, or terminate exactly as an uncaught `std::stof` exception would.
fn parse(argument: &[u8]) -> f32 {
    match stof(argument) {
        Ok(value) => value,
        Err(error) => terminate(error),
    }
}

fn main() {
    let argv: Vec<Vec<u8>> = std::env::args_os()
        .map(|argument| argument.as_os_str().as_bytes().to_vec())
        .collect();
    let argc = argv.len();

    let mut r1 = 0.3f32;
    let mut g1 = 0.4f32;
    let mut b1 = 0.5f32;
    let mut r2 = 0.7f32;
    let mut g2 = 0.2f32;
    // Never overwritten from the command line -- see the note in this file's documentation.
    let b2 = 0.1f32;
    let mut ratio = 0.3f32;

    if argc > 5 {
        r1 = parse(&argv[1]);
        g1 = parse(&argv[2]);
        b1 = parse(&argv[3]);
        r2 = parse(&argv[4]);
        g2 = parse(&argv[5]);
    }
    if argc > 6 {
        ratio = parse(&argv[6]);
    }

    let first = RGB::new(r1, g1, b1);
    let second = RGB::new(r2, g2, b2);
    let result = blend(&first, &second, ratio);

    println!(
        "{} {} {}",
        format_g(result.r),
        format_g(result.g),
        format_g(result.b)
    );
}

