  let a:Vec<String>=std::env::args().collect();
  let n:usize=a[1].parse().unwrap(); let mode:u64=a[2].parse().unwrap();
  let mut r=R(0xA5A5_1234_9876_FEDCu64 ^ mode.wrapping_mul(0x9E3779B97F4A7C15));
  let sp=["nan","-nan","inf","-inf","0","-0.0","0.0","1","-1","0.5","3.4e38","3.5e38","1e20","0.1","1e-5",
          "0.0001","999999.5","1234565","1048565","8388605","9999995","1e-38","1e-40","0x1p-149","0x1p-150",
          "0x10","0x1p4","0X1P-2","0x.8p1","0x1p","0x","inf","infinity","nan(1)","5.",".5","+.5","-.5",
          "1e","1e+","1.5e2x","0.5abc","abc","",".","e5","--1","1e400","1e5000","16777215","1.0000005",
          "0.9999995","9.999995e-05","2097125","4194315","0x1.fffffep-127","0x1.ffffffp-127","1_000","1,5"];
  let mut bad=0usize; let mut ran=0usize;
  for _ in 0..n {
    let argc = match mode { 5 => (r.n()%13) as usize, _ => 6 + (r.n()%3) as usize };
    let v:Vec<String>=(0..argc).map(|_| match mode {
      0 => format!("{:.*}", 1+(r.n()%8) as usize, (r.n()%1_000_000_000) as f64/1e9),
      1 => { loop { let b=(r.n()>>32) as u32; let f=f32::from_bits(b);
                    if f.is_finite() && (f==0.0 || f.abs()>=f32::MIN_POSITIVE) { break format!("{:e}",f) } } }
      2 => sp[(r.n() as usize)%sp.len()].to_string(),
      3 => { let base=[0u32,1,999999,1000000,1234565,1048565,8388605,16777215,9999995,100000,2097152];
             format!("{}", base[(r.n() as usize)%base.len()] as i64 + (r.n()%41) as i64 - 20) }
      4 => { // random junk strings
             let al=b"0123456789abcdefxXpPeE+-., _()\t";
             let l=(r.n()%14) as usize;
             (0..l).map(|_| al[(r.n() as usize)%al.len()] as char).collect() }
      _ => { if r.n()%2==0 { sp[(r.n() as usize)%sp.len()].to_string() }
             else { format!("{:.*}", 1+(r.n()%8) as usize, (r.n()%1_000_000_000) as f64/1e9) } }
    }).collect();
    let o=Command::new(ORACLE).args(&v).output().unwrap();
    let m=Command::new(MINE).args(&v).output().unwrap();
    ran+=1;
    let same = o.stdout==m.stdout && o.stderr==m.stderr && o.status.code()==m.status.code()
               && format!("{:?}",o.status)==format!("{:?}",m.status);
    if !same { bad+=1; if bad<=8 {
      println!("MISMATCH args={:?}\n  oracle out={:?} err={:?} st={:?}\n  mine   out={:?} err={:?} st={:?}",
        v, String::from_utf8_lossy(&o.stdout), String::from_utf8_lossy(&o.stderr), o.status,
           String::from_utf8_lossy(&m.stdout), String::from_utf8_lossy(&m.stderr), m.status); } }
  }
  println!("mode={} cases={} mismatches={}",mode,ran,bad);
}
